select 'aqa-8463-energy-practice', s.id, (select t.id from public.topics t where t.subject_id = s.id and t.name = 'Energy'), 'Energy: exam practice', 'AQA', 30, true, 25, 'Exam practice for one topic: about 30 minutes. You may use a calculator. Answer all the questions. Use g = 9.8 N/kg. Equations you are not expected to remember are given in the question. Show your working in calculations: you can get marks for method even if your final answer is wrong. Questions marked 6 marks are extended answers: write in full sentences and organise your ideas.'
from public.subjects s where s.name = 'Physics'
on conflict (ref) do nothing;
with src as (
  select * from jsonb_to_recordset($q$[{"topic":"Energy","subtopic":"Energy stores and calculating energy changes","spec_ref":"4.1.1.2-4.1.1.3","command_word":"calculate","difficulty":"higher","total_marks":7,"question_text":"A car of mass 1200 kg is travelling at 15 m/s. The driver brakes and the car stops.\n\n(a) Calculate the kinetic energy of the car before it brakes. Show your working. (2 marks)\n\n(b) The brake discs have a total mass of 8.0 kg and a specific heat capacity of 450 J/kg °C. Assume all of the kinetic energy is transferred to the brake discs.\n\nchange in thermal energy = mass × specific heat capacity × temperature change\n\nCalculate the temperature rise of the brake discs. Show your working. (3 marks)\n\n(c) Explain why the actual temperature rise of the discs is less than your answer to (b). (2 marks)","marking_style":"points","scheme":{"max":7,"points":["(a) Ek = ½ × 1200 × 15²","(a) 135 000 J","(b) 135 000 = 8.0 × 450 × Δθ","(b) Δθ = 135 000 ÷ 3600","(b) 37.5 °C (38 °C)","(c) Some of the energy is transferred to other stores, e.g. the tyres, the road or the air (or by sound)","(c) The discs transfer energy to the surroundings by heating as they warm up"],"guidance":"In (b), allow an error carried forward from (a). This question asks for working. A correct final answer with no working scores only the mark(s) for the answer itself, not the method marks. Award each method mark when that step is shown. If the working has a slip (e.g. a wrong number copied) but the final answer is correct, withhold only the mark(s) for the step that is wrong."},"ao_marks":{"AO1":2,"AO2":5},"spag_marks":0,"paper_ref":"aqa-8463-energy-practice","paper_number":1},{"topic":"Energy","subtopic":"Conservation, dissipation and efficiency","spec_ref":"4.1.2.1","command_word":"describe","difficulty":"foundation","total_marks":6,"question_text":"A student wants to find out which of three materials is the best thermal insulator. She has three identical beakers, a kettle, a thermometer, a stopclock and the three materials.\n\nDescribe a method the student could use. Include how she would make it a fair test and how she would decide which material is best.\n\n(6 marks)","marking_style":"levels","scheme":{"levels":[{"level":3,"marks":[5,6],"descriptor":"A clear, logically ordered method that would produce valid results, including what is measured, how it is controlled and how the results are used to reach a conclusion."},{"level":2,"marks":[3,4],"descriptor":"A method with most of the key steps that could produce results, with some idea of how they would be used."},{"level":1,"marks":[1,2],"descriptor":"Some relevant steps, but the method would not produce valid results."}],"indicative":["Wrap each beaker in the same thickness of one of the materials (and leave one unwrapped as a control)","Pour the same volume of hot water from the kettle into each beaker","Use water at the same starting temperature for each beaker","Put a lid on each beaker (made of the same material)","Measure the temperature at the start and at regular intervals (e.g. every 2 minutes) for the same total time","Calculate the temperature drop for each material, or plot cooling curves","The best insulator gives the smallest temperature drop (slowest cooling)","Take care with hot water"],"guidance":"Level 3 needs control of at least two variables and a clear way of deciding which material is best."},"ao_marks":{"AO1":4,"AO2":2},"spag_marks":0,"paper_ref":"aqa-8463-energy-practice","paper_number":2},{"topic":"Energy","subtopic":"Power","spec_ref":"4.1.1.4, 4.1.2.2","command_word":"calculate","difficulty":"foundation","total_marks":6,"question_text":"An electric motor lifts a 2.0 kg mass through a height of 1.5 m in 3.0 s. The input power to the motor is 25 W.\n\n(a) Calculate the gravitational potential energy gained by the mass. Show your working. (2 marks)\n\n(b) Calculate the useful power output of the motor. Show your working. (2 marks)\n\n(c) Calculate the efficiency of the motor. Show your working. (2 marks)","marking_style":"points","scheme":{"max":6,"points":["(a) Ep = mgh = 2.0 × 9.8 × 1.5","(a) 29.4 J","(b) P = E ÷ t = 29.4 ÷ 3.0","(b) 9.8 W","(c) Efficiency = useful power output ÷ total power input = 9.8 ÷ 25","(c) 0.39 (39%)"],"guidance":"Allow an error carried forward from an earlier part. This question asks for working. A correct final answer with no working scores only the mark(s) for the answer itself, not the method marks. Award each method mark when that step is shown. If the working has a slip (e.g. a wrong number copied) but the final answer is correct, withhold only the mark(s) for the step that is wrong."},"ao_marks":{"AO2":6},"spag_marks":0,"paper_ref":"aqa-8463-energy-practice","paper_number":3},{"topic":"Energy","subtopic":"National and global energy resources","spec_ref":"4.1.3","command_word":"explain","difficulty":"higher","total_marks":6,"question_text":"This question is about how the UK generates electricity.\n\nIn 2012, about 40% of the UK's electricity was generated from coal and about 4% from wind. By 2020, about 2% came from coal and about 24% from wind.\n\n(a) Describe how the use of coal and wind changed between 2012 and 2020. (2 marks)\n\n(b) Suggest two reasons for these changes. (2 marks)\n\n(c) Explain why the UK still has gas-fired power stations as well as wind turbines. (2 marks)","marking_style":"points","scheme":{"max":6,"points":["(a) The use of coal fell sharply (from 40% to 2%)","(a) The use of wind increased (about six times, from 4% to 24%)","(b) Concern about carbon dioxide emissions / climate change from burning coal","(b) Government targets or laws to cut emissions, or coal power stations being closed","(b) Wind turbines became cheaper / more were built","(c) Wind is unreliable: turbines do not generate when the wind is too weak or too strong","(c) Gas power stations can be started quickly to meet demand when wind output is low (or demand rises)"],"guidance":"In (b), award up to 2 marks from the 3 points."},"ao_marks":{"AO1":2,"AO3":4},"spag_marks":0,"paper_ref":"aqa-8463-energy-practice","paper_number":4}]$q$::jsonb) as x(topic text, subtopic text, spec_ref text, command_word text, difficulty text, total_marks int, question_text text, marking_style text, scheme jsonb, ao_marks jsonb, spag_marks int, paper_ref text, paper_number int)
),
ins as (
