select 'aqa-8463-forces-practice', s.id, (select t.id from public.topics t where t.subject_id = s.id and t.name = 'Forces'), 'Forces: exam practice', 'AQA', 30, true, 25, 'Exam practice for one topic: about 30 minutes. You may use a calculator. Answer all the questions. Use g = 9.8 N/kg. Equations you are not expected to remember are given in the question. Show your working in calculations: you can get marks for method even if your final answer is wrong. Questions marked 6 marks are extended answers: write in full sentences and organise your ideas.'
from public.subjects s where s.name = 'Physics'
on conflict (ref) do nothing;
with src as (
  select * from jsonb_to_recordset($q$[{"topic":"Forces","subtopic":"Momentum","spec_ref":"4.5.7.1-4.5.7.3","command_word":"explain","difficulty":"higher","total_marks":7,"question_text":"A cricket ball of mass 0.16 kg is travelling at 25 m/s. A fielder catches it and brings it to rest in 0.080 s.\n\n(a) Calculate the momentum of the ball before it is caught. Show your working. (2 marks)\n\n(b) Calculate the average force on the ball while it is being caught. Show your working. (2 marks)\n\n(c) Explain why the fielder moves their hands backwards while catching the ball. (3 marks)","marking_style":"points","scheme":{"max":7,"points":["(a) p = mv = 0.16 × 25","(a) 4.0 kg m/s","(b) F = change in momentum ÷ time = 4.0 ÷ 0.080","(b) 50 N","(c) Moving the hands back increases the time taken for the ball to stop","(c) So the rate of change of momentum is smaller","(c) So the force on the hands is smaller, which hurts less"],"guidance":"In (b), allow an error carried forward from (a). This question asks for working. A correct final answer with no working scores only the mark(s) for the answer itself, not the method marks. Award each method mark when that step is shown. If the working has a slip (e.g. a wrong number copied) but the final answer is correct, withhold only the mark(s) for the step that is wrong."},"ao_marks":{"AO1":2,"AO2":5},"spag_marks":0,"paper_ref":"aqa-8463-forces-practice","paper_number":1},{"topic":"Forces","subtopic":"Newton's laws of motion","spec_ref":"4.5.6.2.2","command_word":"describe","difficulty":"higher","total_marks":6,"question_text":"A student wants to investigate how the acceleration of a trolley depends on the resultant force on it.\n\nShe has a trolley, a long bench, a pulley, a string, a set of 1 N masses on a hanger, light gates connected to a data logger, and a ruler.\n\nDescribe a method the student could use. Include how she would keep the investigation fair and how she would process her results.\n\n(6 marks)","marking_style":"levels","scheme":{"levels":[{"level":3,"marks":[5,6],"descriptor":"A clear, logically ordered method that would produce valid results, including what is measured, how it is controlled and how the results are used to reach a conclusion."},{"level":2,"marks":[3,4],"descriptor":"A method with most of the key steps that could produce results, with some idea of how they would be used."},{"level":1,"marks":[1,2],"descriptor":"Some relevant steps, but the method would not produce valid results."}],"indicative":["Attach the trolley to the masses with a string over a pulley at the end of the bench","The weight of the hanging masses provides the accelerating force","Release the trolley from rest at the same point each time","Use the light gates (or a stopclock and marked distances) to measure the acceleration","Move masses from the trolley to the hanger so the total mass being accelerated stays the same","Repeat for several forces (e.g. 1 N to 5 N), taking repeat readings and calculating means","Plot acceleration against force","A straight line through the origin shows acceleration is directly proportional to force"],"guidance":"Level 3 needs the total mass kept constant and a graph of acceleration against force."},"ao_marks":{"AO1":4,"AO2":2},"spag_marks":0,"paper_ref":"aqa-8463-forces-practice","paper_number":2},{"topic":"Forces","subtopic":"Describing motion: speed, velocity, acceleration and graphs","spec_ref":"4.5.6.1.2, 4.5.6.1.5","command_word":"calculate","difficulty":"foundation","total_marks":6,"question_text":"A cyclist rides 1.2 km in 4.0 minutes.\n\n(a) Calculate her average speed in m/s. Show your working. (2 marks)\n\n(b) Later, she starts from rest and accelerates uniformly to 6.0 m/s in 3.0 s.\n\n(i) Calculate her acceleration. Show your working. (2 marks)\n(ii) Calculate the distance she travels in these 3.0 s, using the area under a velocity–time graph. Show your working. (2 marks)","marking_style":"points","scheme":{"max":6,"points":["(a) speed = distance ÷ time = 1200 ÷ 240","(a) 5.0 m/s","(b)(i) a = Δv ÷ t = 6.0 ÷ 3.0","(b)(i) 2.0 m/s²","(b)(ii) Distance = area of triangle = ½ × 3.0 × 6.0","(b)(ii) 9.0 m"],"guidance":"In (a), 0.3 (no unit conversion) scores 1. This question asks for working. A correct final answer with no working scores only the mark(s) for the answer itself, not the method marks. Award each method mark when that step is shown. If the working has a slip (e.g. a wrong number copied) but the final answer is correct, withhold only the mark(s) for the step that is wrong."},"ao_marks":{"AO2":6},"spag_marks":0,"paper_ref":"aqa-8463-forces-practice","paper_number":3},{"topic":"Forces","subtopic":"Moments, levers and gears","spec_ref":"4.5.4","command_word":"calculate","difficulty":"foundation","total_marks":6,"question_text":"This question is about moments.\n\n(a) A metre rule is balanced at its centre. A 50 N weight hangs 0.30 m to the left of the centre. Calculate how far to the right of the centre a 75 N weight must hang to balance the rule. Show your working. (3 marks)\n\n(b) Explain why a tower crane has a heavy counterweight on the opposite side to the load. (2 marks)\n\n(c) State the principle of moments. (1 mark)","marking_style":"points","scheme":{"max":6,"points":["(a) Anticlockwise moment = 50 × 0.30 = 15 N m","(a) 75 × d = 15","(a) d = 0.20 m","(b) The load produces a moment about the tower that could make it topple","(b) The counterweight produces a moment in the opposite direction, which balances it","(c) For an object in balance, the total clockwise moment about a pivot equals the total anticlockwise moment about that pivot"],"guidance":"This question asks for working. A correct final answer with no working scores only the mark(s) for the answer itself, not the method marks. Award each method mark when that step is shown. If the working has a slip (e.g. a wrong number copied) but the final answer is correct, withhold only the mark(s) for the step that is wrong."},"ao_marks":{"AO1":2,"AO2":4},"spag_marks":0,"paper_ref":"aqa-8463-forces-practice","paper_number":4}]$q$::jsonb) as x(topic text, subtopic text, spec_ref text, command_word text, difficulty text, total_marks int, question_text text, marking_style text, scheme jsonb, ao_marks jsonb, spag_marks int, paper_ref text, paper_number int)
),
ins as (
  insert into public.fm_exam_questions (subtopic_id, topic_id, question_text, command_word, total_marks, difficulty, exam_board, spec_ref, active, paper_ref, paper_number)
  select st.id, t.id, src.question_text, src.command_word, src.total_marks, src.difficulty, 'AQA', src.spec_ref, true, src.paper_ref, src.paper_number
  from src
  join public.subjects s on s.name = 'Physics'
  join public.topics t on t.subject_id = s.id and t.name = src.topic
  join public.subtopics st on st.topic_id = t.id and st.name = src.subtopic
  where not exists (select 1 from public.fm_exam_questions e where e.question_text = src.question_text)
  returning id, question_text
)
insert into public.fm_mark_schemes (question_id, marking_style, scheme, ao_marks, spag_marks)
select ins.id, src.marking_style, src.scheme, src.ao_marks, src.spag_marks from ins join src using (question_text);

-- Physics (AQA): 4 questions
insert into public.fm_papers (ref, subject_id, topic_id, title, exam_board, duration_minutes, calculator, total_marks, instructions)
select 'aqa-8463-magnetism-practice', s.id, (select t.id from public.topics t where t.subject_id = s.id and t.name = 'Magnetism and Electromagnetism'), 'Magnetism and Electromagnetism: exam practice', 'AQA', 30, true, 25, 'Exam practice for one topic: about 30 minutes. You may use a calculator. Answer all the questions. Use g = 9.8 N/kg. Equations you are not expected to remember are given in the question. Show your working in calculations: you can get marks for method even if your final answer is wrong. Questions marked 6 marks are extended answers: write in full sentences and organise your ideas.'
from public.subjects s where s.name = 'Physics'
on conflict (ref) do nothing;
with src as (
  select * from jsonb_to_recordset($q$[{"topic":"Magnetism and Electromagnetism","subtopic":"Induced potential, generators and transformers","spec_ref":"4.7.3.1, 4.7.3.3","command_word":"explain","difficulty":"higher","total_marks":6,"question_text":"A moving-coil microphone contains a coil of wire attached to a thin diaphragm. The coil is around one pole of a permanent magnet.\n\nExplain how the microphone produces an electrical signal from sound waves.\n\n(6 marks)","marking_style":"levels","scheme":{"levels":[{"level":3,"marks":[5,6],"descriptor":"A clear, logically ordered explanation linking the sound wave to the movement of the coil, the induced potential difference and how the signal matches the sound."},{"level":2,"marks":[3,4],"descriptor":"Some explanation of how movement of the coil in the magnetic field produces a potential difference."},{"level":1,"marks":[1,2],"descriptor":"Simple statements about sound, coils or magnets, with little explanation."}],"indicative":["Sound waves are pressure variations that make the diaphragm vibrate","The coil, attached to the diaphragm, moves backwards and forwards with it","The coil moves in the magnetic field of the magnet","This induces a potential difference across the coil (the generator effect)","If the coil is part of a complete circuit, an induced current flows","The direction of the induced pd reverses each time the coil changes direction, so it is alternating","Louder sounds give larger movements and a larger pd; higher frequencies give a higher frequency signal","So the electrical signal has the same pattern (frequency and amplitude) as the sound wave"],"guidance":"Level 3 needs the coil moving in the field, an induced pd, and the signal matching the sound."},"ao_marks":{"AO1":4,"AO2":2},"spag_marks":0,"paper_ref":"aqa-8463-magnetism-practice","paper_number":1},{"topic":"Magnetism and Electromagnetism","subtopic":"Electromagnetism and the motor effect","spec_ref":"4.7.2.2","command_word":"calculate","difficulty":"higher","total_marks":7,"question_text":"A wire of length 0.20 m carries a current of 2.5 A. It is at right angles to a magnetic field of flux density 0.15 T.\n\nforce = magnetic flux density × current × length\n\n(a) Calculate the force on the wire. Show your working. (2 marks)\n\n(b) Fleming's left-hand rule is used to find the direction of the force. State what the thumb, first finger and second finger each represent. (3 marks)\n\n(c) The wire is turned so that it is parallel to the magnetic field. What is the force on the wire now? Give a reason. (2 marks)","marking_style":"points","scheme":{"max":7,"points":["(a) F = BIl = 0.15 × 2.5 × 0.20","(a) 0.075 N","(b) Thumb: the direction of the force (motion)","(b) First finger: the direction of the magnetic field","(b) Second finger: the direction of the current","(c) Zero","(c) There is no force when the current is parallel to the field (the wire does not cut across the field lines)"],"guidance":"This question asks for working. A correct final answer with no working scores only the mark(s) for the answer itself, not the method marks. Award each method mark when that step is shown. If the working has a slip (e.g. a wrong number copied) but the final answer is correct, withhold only the mark(s) for the step that is wrong."},"ao_marks":{"AO1":4,"AO2":3},"spag_marks":0,"paper_ref":"aqa-8463-magnetism-practice","paper_number":2},{"topic":"Magnetism and Electromagnetism","subtopic":"Induced potential, generators and transformers","spec_ref":"4.7.3.2, 4.7.3.4","command_word":"calculate","difficulty":"higher","total_marks":6,"question_text":"This question is about generators and transformers.\n\n(a) The coil of an alternator is made to rotate faster. Give two effects this has on the output. (2 marks)\n\n(b) A step-up transformer has 120 turns on its primary coil and 2400 turns on its secondary coil. The primary pd is 12 V.\n\npotential difference across primary ÷ potential difference across secondary = number of turns on primary ÷ number of turns on secondary\n\nCalculate the secondary pd. Show your working. (2 marks)\n\n(c) Explain why the coils of a transformer are wound on an iron core. (2 marks)","marking_style":"points","scheme":{"max":6,"points":["(a) The peak (maximum) potential difference increases","(a) The frequency of the alternating pd increases","(b) Vs = 12 × 2400 ÷ 120","(b) 240 V","(c) Iron is easily magnetised (a magnetic material)","(c) It carries the changing magnetic field from the primary coil through the secondary coil"],"guidance":"This question asks for working. A correct final answer with no working scores only the mark(s) for the answer itself, not the method marks. Award each method mark when that step is shown. If the working has a slip (e.g. a wrong number copied) but the final answer is correct, withhold only the mark(s) for the step that is wrong."},"ao_marks":{"AO1":4,"AO2":2},"spag_marks":0,"paper_ref":"aqa-8463-magnetism-practice","paper_number":3},{"topic":"Magnetism and Electromagnetism","subtopic":"Permanent and induced magnetism and magnetic fields","spec_ref":"4.7.1.1-4.7.1.2","command_word":"describe","difficulty":"foundation","total_marks":6,"question_text":"This question is about magnets.\n\n(a) A compass needle points north when it is away from any magnets. Explain what this shows about the Earth. (2 marks)\n\n(b) What is a magnetic material? Give two examples. (2 marks)\n\n(c) Two magnets attract each other without touching. What does this tell you about the poles facing each other and about the type of force? (2 marks)","marking_style":"points","scheme":{"max":6,"points":["(a) The Earth has a magnetic field","(a) The compass needle (a small magnet) lines up with the Earth's field; this is evidence that the Earth's core is magnetic","(b) A material that is attracted to a magnet (and can be magnetised)","(b) Two of iron, steel, cobalt, nickel","(c) They are opposite poles (north facing south)","(c) The magnetic force is a non-contact force"]},"ao_marks":{"AO1":5,"AO2":1},"spag_marks":0,"paper_ref":"aqa-8463-magnetism-practice","paper_number":4}]$q$::jsonb) as x(topic text, subtopic text, spec_ref text, command_word text, difficulty text, total_marks int, question_text text, marking_style text, scheme jsonb, ao_marks jsonb, spag_marks int, paper_ref text, paper_number int)
),
ins as (
  insert into public.fm_exam_questions (subtopic_id, topic_id, question_text, command_word, total_marks, difficulty, exam_board, spec_ref, active, paper_ref, paper_number)
  select st.id, t.id, src.question_text, src.command_word, src.total_marks, src.difficulty, 'AQA', src.spec_ref, true, src.paper_ref, src.paper_number
  from src
  join public.subjects s on s.name = 'Physics'
  join public.topics t on t.subject_id = s.id and t.name = src.topic
  join public.subtopics st on st.topic_id = t.id and st.name = src.subtopic
  where not exists (select 1 from public.fm_exam_questions e where e.question_text = src.question_text)
  returning id, question_text
)
insert into public.fm_mark_schemes (question_id, marking_style, scheme, ao_marks, spag_marks)
select ins.id, src.marking_style, src.scheme, src.ao_marks, src.spag_marks from ins join src using (question_text);

