insert into public.fm_papers (ref, subject_id, topic_id, title, exam_board, duration_minutes, calculator, total_marks, instructions)
select 'aqa-8463-particle-model-practice', s.id, (select t.id from public.topics t where t.subject_id = s.id and t.name = 'Particle Model of Matter'), 'Particle Model of Matter: exam practice', 'AQA', 30, true, 25, 'Exam practice for one topic: about 30 minutes. You may use a calculator. Answer all the questions. Use g = 9.8 N/kg. Equations you are not expected to remember are given in the question. Show your working in calculations: you can get marks for method even if your final answer is wrong. Questions marked 6 marks are extended answers: write in full sentences and organise your ideas.'
from public.subjects s where s.name = 'Physics'
on conflict (ref) do nothing;
with src as (
  select * from jsonb_to_recordset($q$[{"topic":"Particle Model of Matter","subtopic":"Density and changes of state","spec_ref":"4.3.1.1-4.3.1.2","command_word":"explain","difficulty":"foundation","total_marks":6,"question_text":"Water can be a solid (ice), a liquid or a gas (steam).\n\nUse the particle model to explain the differences between the three states, and what happens to the particles when ice melts and when water boils.\n\n(6 marks)","marking_style":"levels","scheme":{"levels":[{"level":3,"marks":[5,6],"descriptor":"A clear, detailed explanation of the arrangement and movement of particles in all three states, linked to density, and of what happens to the particles and their energy during melting and boiling."},{"level":2,"marks":[3,4],"descriptor":"Some description of the particles in at least two states and some idea of what happens when a substance changes state."},{"level":1,"marks":[1,2],"descriptor":"Simple statements about solids, liquids or gases, with little explanation."}],"indicative":["Solid: particles closely packed in a regular arrangement, vibrating about fixed positions","Liquid: particles close together but randomly arranged, able to move past each other","Gas: particles far apart, moving quickly in random directions","Gases are much less dense because the particles are far apart","When ice melts, energy is used to overcome (break) the forces between the particles, so they can move around","When water boils, the particles gain enough energy to escape from the liquid completely","During melting and boiling the temperature stays constant: the energy increases the potential energy (internal energy), not the kinetic energy","Mass is conserved in a change of state; it is a physical change, so it can be reversed"],"guidance":"Level 3 needs all three states and both changes of state."},"ao_marks":{"AO1":6},"spag_marks":0,"paper_ref":"aqa-8463-particle-model-practice","paper_number":1},{"topic":"Particle Model of Matter","subtopic":"Internal energy and specific latent heat","spec_ref":"4.3.2.2-4.3.2.3","command_word":"calculate","difficulty":"higher","total_marks":7,"question_text":"A 0.20 kg block of ice at −10 °C is heated until it becomes water at 20 °C.\n\nSpecific heat capacity of ice = 2100 J/kg °C\nSpecific latent heat of fusion of ice = 334 000 J/kg\nSpecific heat capacity of water = 4200 J/kg °C\nchange in thermal energy = mass × specific heat capacity × temperature change\nthermal energy for a change of state = mass × specific latent heat\n\n(a) Calculate the energy needed to warm the ice from −10 °C to 0 °C. Show your working. (2 marks)\n\n(b) Calculate the energy needed to melt the ice at 0 °C. Show your working. (2 marks)\n\n(c) Calculate the energy needed to warm the water from 0 °C to 20 °C. (1 mark)\n\n(d) Calculate the total energy needed. (1 mark)\n\n(e) Which stage needs the most energy? (1 mark)","marking_style":"points","scheme":{"max":7,"points":["(a) ΔE = 0.20 × 2100 × 10","(a) 4200 J","(b) E = mL = 0.20 × 334 000","(b) 66 800 J","(c) 0.20 × 4200 × 20 = 16 800 J","(d) 87 800 J","(e) Melting the ice"],"guidance":"In (d), allow an error carried forward from (a) to (c). This question asks for working. A correct final answer with no working scores only the mark(s) for the answer itself, not the method marks. Award each method mark when that step is shown. If the working has a slip (e.g. a wrong number copied) but the final answer is correct, withhold only the mark(s) for the step that is wrong."},"ao_marks":{"AO2":7},"spag_marks":0,"paper_ref":"aqa-8463-particle-model-practice","paper_number":2},{"topic":"Particle Model of Matter","subtopic":"Particle motion in gases and gas pressure","spec_ref":"4.3.3.1-4.3.3.2","command_word":"explain","difficulty":"higher","total_marks":6,"question_text":"A gas is trapped in a sealed syringe. Its temperature stays constant.\n\n(a) The gas has a pressure of 100 kPa and a volume of 60 cm³. The plunger is pushed in until the volume is 40 cm³.\n\npressure × volume = constant\n\nCalculate the new pressure. Show your working. (2 marks)\n\n(b) Explain, in terms of particles, why the pressure increases when the volume decreases. (2 marks)\n\n(c) Describe how the motion of the gas particles is related to the temperature of the gas. (2 marks)","marking_style":"points","scheme":{"max":6,"points":["(a) p₂ = 100 × 60 ÷ 40","(a) 150 kPa","(b) The particles have less space, so they hit the walls more often","(b) So there are more collisions per second on each unit area, giving a larger force per unit area (pressure)","(c) The particles move constantly in random directions","(c) The higher the temperature, the greater the average kinetic energy (speed) of the particles"],"guidance":"In (b), 'the particles move faster' scores 0: the temperature is constant. This question asks for working. A correct final answer with no working scores only the mark(s) for the answer itself, not the method marks. Award each method mark when that step is shown. If the working has a slip (e.g. a wrong number copied) but the final answer is correct, withhold only the mark(s) for the step that is wrong."},"ao_marks":{"AO1":2,"AO2":4},"spag_marks":0,"paper_ref":"aqa-8463-particle-model-practice","paper_number":3},{"topic":"Particle Model of Matter","subtopic":"Density and changes of state","spec_ref":"4.3.1.1, 4.3.2.1","command_word":"calculate","difficulty":"foundation","total_marks":6,"question_text":"(a) What is meant by the internal energy of a substance? (2 marks)\n\n(b) A metal block measures 5.0 cm × 4.0 cm × 2.0 cm and has a mass of 0.304 kg. Calculate the density of the metal in kg/m³. Show your working. (3 marks)\n\n(c) The block is melted. What happens to its mass? (1 mark)","marking_style":"points","scheme":{"max":6,"points":["(a) The total energy stored by the particles (atoms or molecules) of the substance","(a) The sum of their kinetic energy and potential energy","(b) Volume = 5.0 × 4.0 × 2.0 = 40 cm³ = 4.0 × 10⁻⁵ m³","(b) ρ = m ÷ V = 0.304 ÷ 4.0 × 10⁻⁵","(b) 7600 kg/m³","(c) It stays the same (mass is conserved)"],"guidance":"In (b), 7.6 g/cm³ from correct working scores 2. This question asks for working. A correct final answer with no working scores only the mark(s) for the answer itself, not the method marks. Award each method mark when that step is shown. If the working has a slip (e.g. a wrong number copied) but the final answer is correct, withhold only the mark(s) for the step that is wrong."},"ao_marks":{"AO1":3,"AO2":3},"spag_marks":0,"paper_ref":"aqa-8463-particle-model-practice","paper_number":4}]$q$::jsonb) as x(topic text, subtopic text, spec_ref text, command_word text, difficulty text, total_marks int, question_text text, marking_style text, scheme jsonb, ao_marks jsonb, spag_marks int, paper_ref text, paper_number int)
),
ins as (
  insert into public.fm_exam_questions (subtopic_id, topic_id, question_text, command_word, total_marks, difficulty, exam_board, spec_ref, active, paper_ref, paper_number)
  select st.id, t.id, src.question_text, src.command_word, src.total_marks, src.difficulty, 'AQA', src.spec_ref, true, src.paper_ref, src.paper_number
  from src
  join public.subjects s on s.name = 'Physics'
  join public.topics t on t.subject_id = s.id and t.name = src.topic
  join public.subtopics st on st.topic_id = t.id and st.name = src.subtopic
  where not exists (select 1 from public.fm_exam_questions e where e.question_text = src.question_text)
  returning id, question_text
)
insert into public.fm_mark_schemes (question_id, marking_style, scheme, ao_marks, spag_marks)
select ins.id, src.marking_style, src.scheme, src.ao_marks, src.spag_marks from ins join src using (question_text);

-- Physics (AQA): 3 questions
insert into public.fm_papers (ref, subject_id, topic_id, title, exam_board, duration_minutes, calculator, total_marks, instructions)
select 'aqa-8463-space-practice', s.id, (select t.id from public.topics t where t.subject_id = s.id and t.name = 'Space Physics'), 'Space Physics: exam practice', 'AQA', 25, true, 19, 'Exam practice for one topic: about 25 minutes. You may use a calculator. Answer all the questions. Use g = 9.8 N/kg. Equations you are not expected to remember are given in the question. Show your working in calculations: you can get marks for method even if your final answer is wrong. Questions marked 6 marks are extended answers: write in full sentences and organise your ideas.'
from public.subjects s where s.name = 'Physics'
on conflict (ref) do nothing;
with src as (
  select * from jsonb_to_recordset($q$[{"topic":"Space Physics","subtopic":"Red-shift and the Big Bang","spec_ref":"4.8.2","command_word":"explain","difficulty":"higher","total_marks":6,"question_text":"Explain how observations of light from distant galaxies support the Big Bang theory, and what more recent observations suggest about the universe.\n\n(6 marks)","marking_style":"levels","scheme":{"levels":[{"level":3,"marks":[5,6],"descriptor":"A clear explanation of red-shift, how it shows the universe is expanding and supports the Big Bang, plus the more recent evidence from supernovae and what it suggests."},{"level":2,"marks":[3,4],"descriptor":"Some explanation of red-shift and how it supports the Big Bang, possibly without the more recent observations."},{"level":1,"marks":[1,2],"descriptor":"Simple statements about galaxies, red-shift or the Big Bang."}],"indicative":["Light from distant galaxies is red-shifted: its wavelength is longer than expected","This means the galaxies are moving away from us","The further away a galaxy is, the greater its red-shift, so the faster it is moving away","So the whole universe is expanding","If it is expanding, it must once have been much smaller: it began from a very small, extremely hot and dense region (the Big Bang)","Since 1998, observations of supernovae suggest that distant galaxies are moving away faster and faster: the expansion is accelerating","Scientists suggest this is caused by dark energy, and there may be dark mass too","These are not yet understood, so the theory may change as new evidence is found"],"guidance":"Level 3 needs red-shift linked to expansion and the Big Bang, and at least one more recent observation."},"ao_marks":{"AO1":4,"AO3":2},"spag_marks":0,"paper_ref":"aqa-8463-space-practice","paper_number":1},{"topic":"Space Physics","subtopic":"The solar system and the life cycle of a star","spec_ref":"4.8.1.2","command_word":"explain","difficulty":"foundation","total_marks":7,"question_text":"This question is about stars.\n\n(a) Name the force that pulls clouds of dust and gas together to form a star. (1 mark)\n\n(b) Explain what has to happen inside a protostar for it to become a main sequence star. (2 marks)\n\n(c) Describe what will eventually happen to the Sun after its main sequence stage. (2 marks)\n\n(d) Elements heavier than iron are found on Earth. Explain how they got here. (2 marks)","marking_style":"points","scheme":{"max":7,"points":["(a) Gravity","(b) The temperature and pressure in the core become high enough","(b) For hydrogen nuclei to fuse to form helium (nuclear fusion starts)","(c) It will swell to become a red giant","(c) Then it will become a white dwarf (and eventually a black dwarf)","(d) Elements heavier than iron were made in a supernova (the explosion of a massive star)","(d) The supernova spread them through space, and our solar system formed from that material"]},"ao_marks":{"AO1":5,"AO2":2},"spag_marks":0,"paper_ref":"aqa-8463-space-practice","paper_number":2},{"topic":"Space Physics","subtopic":"Orbital motion, natural and artificial satellites","spec_ref":"4.8.1.1, 4.8.1.3","command_word":"explain","difficulty":"higher","total_marks":6,"question_text":"This question is about the solar system and orbits.\n\n(a) Describe what makes up our solar system. (2 marks)\n\n(b) Satellite A orbits 400 km above the Earth's surface. Satellite B orbits 36 000 km above it. Which satellite moves faster? Explain your answer. (2 marks)\n\n(c) What force keeps the planets in orbit around the Sun? (1 mark)\n\n(d) Give one use of artificial satellites. (1 mark)","marking_style":"points","scheme":{"max":6,"points":["(a) One star (the Sun) and eight planets","(a) Dwarf planets (e.g. Pluto) and natural satellites (moons), plus asteroids and comets","(b) Satellite A moves faster","(b) It is closer, where the gravitational force is stronger, so it must move faster to stay in a stable orbit","(c) Gravity (the gravitational attraction of the Sun)","(d) A valid use, e.g. communications, weather monitoring, satellite navigation (GPS), observing the Earth or space"]},"ao_marks":{"AO1":4,"AO2":2},"spag_marks":0,"paper_ref":"aqa-8463-space-practice","paper_number":3}]$q$::jsonb) as x(topic text, subtopic text, spec_ref text, command_word text, difficulty text, total_marks int, question_text text, marking_style text, scheme jsonb, ao_marks jsonb, spag_marks int, paper_ref text, paper_number int)
),
ins as (
  insert into public.fm_exam_questions (subtopic_id, topic_id, question_text, command_word, total_marks, difficulty, exam_board, spec_ref, active, paper_ref, paper_number)
  select st.id, t.id, src.question_text, src.command_word, src.total_marks, src.difficulty, 'AQA', src.spec_ref, true, src.paper_ref, src.paper_number
  from src
  join public.subjects s on s.name = 'Physics'
  join public.topics t on t.subject_id = s.id and t.name = src.topic
  join public.subtopics st on st.topic_id = t.id and st.name = src.subtopic
  where not exists (select 1 from public.fm_exam_questions e where e.question_text = src.question_text)
  returning id, question_text
)
insert into public.fm_mark_schemes (question_id, marking_style, scheme, ao_marks, spag_marks)
select ins.id, src.marking_style, src.scheme, src.ao_marks, src.spag_marks from ins join src using (question_text);

-- Physics (AQA): 4 questions
insert into public.fm_papers (ref, subject_id, topic_id, title, exam_board, duration_minutes, calculator, total_marks, instructions)
select 'aqa-8463-waves-practice', s.id, (select t.id from public.topics t where t.subject_id = s.id and t.name = 'Waves'), 'Waves: exam practice', 'AQA', 30, true, 25, 'Exam practice for one topic: about 30 minutes. You may use a calculator. Answer all the questions. Use g = 9.8 N/kg. Equations you are not expected to remember are given in the question. Show your working in calculations: you can get marks for method even if your final answer is wrong. Questions marked 6 marks are extended answers: write in full sentences and organise your ideas.'
from public.subjects s where s.name = 'Physics'
on conflict (ref) do nothing;
with src as (
  select * from jsonb_to_recordset($q$[{"topic":"Waves","subtopic":"Electromagnetic waves: properties, uses and hazards","spec_ref":"4.6.2.2","command_word":"describe","difficulty":"higher","total_marks":6,"question_text":"A student wants to investigate how light is refracted by a rectangular glass block.\n\nShe has a ray box, a glass block, a protractor, a ruler, a pencil and a sheet of paper.\n\nDescribe a method the student could use, including the measurements she should take and what she would expect to find.\n\n(6 marks)","marking_style":"levels","scheme":{"levels":[{"level":3,"marks":[5,6],"descriptor":"A clear, logically ordered method that would produce valid results, including what is measured, how it is controlled and how the results are used to reach a conclusion."},{"level":2,"marks":[3,4],"descriptor":"A method with most of the key steps that could produce results, with some idea of how they would be used."},{"level":1,"marks":[1,2],"descriptor":"Some relevant steps, but the method would not produce valid results."}],"indicative":["Place the glass block on the paper and draw around it","Draw a normal (at 90°) to one side of the block","Shine a ray of light from the ray box at the block, hitting it where the normal meets the surface","Mark the path of the ray going in and coming out with crosses or dots, then remove the block and join them up","Measure the angle of incidence and the angle of refraction from the normal with the protractor","Repeat for several angles of incidence","Work in a darkened room so the ray is easy to see","The ray bends towards the normal entering the glass and away from the normal leaving it, because light slows down in glass"],"guidance":"Level 3 needs angles measured from the normal and the expected result."},"ao_marks":{"AO1":4,"AO2":2},"spag_marks":0,"paper_ref":"aqa-8463-waves-practice","paper_number":1},{"topic":"Waves","subtopic":"Transverse and longitudinal waves and the wave equation","spec_ref":"4.6.1.2","command_word":"calculate","difficulty":"higher","total_marks":7,"question_text":"A sound wave has a frequency of 500 Hz and a wavelength of 0.68 m in air.\n\n(a) Calculate the speed of the sound wave in air. Show your working. (2 marks)\n\n(b) The sound wave passes into water, where its speed is 1500 m/s. Calculate its wavelength in water. Show your working. (2 marks)\n\n(c) What happens to the frequency of the wave when it passes into water? (1 mark)\n\n(d) Describe a simple method to measure the speed of sound in air outdoors. (2 marks)","marking_style":"points","scheme":{"max":7,"points":["(a) v = fλ = 500 × 0.68","(a) 340 m/s","(b) λ = v ÷ f = 1500 ÷ 500","(b) 3.0 m","(c) It stays the same","(d) Measure a long distance (e.g. 100 m or more) between a sound source (e.g. clapping boards) and an observer","(d) Time how long the sound takes to travel that distance (e.g. start the stopclock when the boards are seen to clap); speed = distance ÷ time"],"guidance":"This question asks for working. A correct final answer with no working scores only the mark(s) for the answer itself, not the method marks. Award each method mark when that step is shown. If the working has a slip (e.g. a wrong number copied) but the final answer is correct, withhold only the mark(s) for the step that is wrong."},"ao_marks":{"AO1":3,"AO2":4},"spag_marks":0,"paper_ref":"aqa-8463-waves-practice","paper_number":2},{"topic":"Waves","subtopic":"Electromagnetic waves: properties, uses and hazards","spec_ref":"4.6.2.1, 4.6.2.3-4.6.2.4","command_word":"explain","difficulty":"foundation","total_marks":6,"question_text":"This question is about the electromagnetic spectrum.\n\n(a) Give one use for each of these electromagnetic waves: radio waves, ultraviolet and gamma rays. (3 marks)\n\n(b) Explain why gamma rays are more dangerous to people than radio waves. (2 marks)\n\n(c) Which type of electromagnetic wave has the shortest wavelength? (1 mark)","marking_style":"points","scheme":{"max":6,"points":["(a) Radio waves: television or radio broadcasting / communications","(a) Ultraviolet: energy-efficient lamps / sun tanning / detecting forged banknotes","(a) Gamma rays: medical imaging or treatment (killing cancer cells) / sterilising equipment","(b) Gamma rays have a much higher frequency, so they transfer more energy","(b) Gamma rays are ionising, so they can damage cells and cause mutations (cancer); radio waves are not ionising","(c) Gamma rays"]},"ao_marks":{"AO1":5,"AO2":1},"spag_marks":0,"paper_ref":"aqa-8463-waves-practice","paper_number":3},{"topic":"Waves","subtopic":"Lenses","spec_ref":"4.6.2.5","command_word":"calculate","difficulty":"foundation","total_marks":6,"question_text":"An object is placed a long way from a convex lens. The lens forms an image on a screen.\n\n(a) Describe the image formed on the screen. (3 marks)\n\n(b) The object is 3.0 cm tall and the image is 1.2 cm tall. Calculate the magnification. Show your working. (2 marks)\n\n(c) Explain why magnification has no unit. (1 mark)","marking_style":"points","scheme":{"max":6,"points":["(a) Real (it can be projected onto a screen)","(a) Inverted (upside down)","(a) Smaller than the object (diminished)","(b) magnification = image height ÷ object height = 1.2 ÷ 3.0","(b) 0.40","(c) It is a ratio of two lengths with the same unit, so the units cancel"],"guidance":"This question asks for working. A correct final answer with no working scores only the mark(s) for the answer itself, not the method marks. Award each method mark when that step is shown. If the working has a slip (e.g. a wrong number copied) but the final answer is correct, withhold only the mark(s) for the step that is wrong."},"ao_marks":{"AO1":3,"AO2":3},"spag_marks":0,"paper_ref":"aqa-8463-waves-practice","paper_number":4}]$q$::jsonb) as x(topic text, subtopic text, spec_ref text, command_word text, difficulty text, total_marks int, question_text text, marking_style text, scheme jsonb, ao_marks jsonb, spag_marks int, paper_ref text, paper_number int)
),
ins as (
  insert into public.fm_exam_questions (subtopic_id, topic_id, question_text, command_word, total_marks, difficulty, exam_board, spec_ref, active, paper_ref, paper_number)
  select st.id, t.id, src.question_text, src.command_word, src.total_marks, src.difficulty, 'AQA', src.spec_ref, true, src.paper_ref, src.paper_number
  from src
  join public.subjects s on s.name = 'Physics'
  join public.topics t on t.subject_id = s.id and t.name = src.topic
  join public.subtopics st on st.topic_id = t.id and st.name = src.subtopic
  where not exists (select 1 from public.fm_exam_questions e where e.question_text = src.question_text)
  returning id, question_text
)
insert into public.fm_mark_schemes (question_id, marking_style, scheme, ao_marks, spag_marks)
select ins.id, src.marking_style, src.scheme, src.ao_marks, src.spag_marks from ins join src using (question_text);

